namespace ghidra.app.plugin.core.debug.service.tracemgr;



using ghidra.app.plugin.core.debug.service.tracemgr.DebuggerTraceManagerServicePlugin;
using ghidra.framework.plugintool;
using ghidra.trace.model;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

public class SaveNewTraceTask : AbstractSaveTraceTask {
	public SaveNewTraceTask(PluginTool tool, Trace trace, AskTraceResult asked, bool force) : base("Save trace " + trace.getName(), tool, trace, asked, force)
    {
	}

	/* @Override */
	protected void saveTrace(TaskMonitor monitor)
    {
		string filename = asked.name();
		for (int i = 1;; i++) {
			try {
				asked.parent().createFile(filename, trace, monitor);
				break; // success, so fall through
			}
			catch (DuplicateFileException e) {
				filename = "%s.%d".formatted(asked.name(), i);
			}
		}
		trace.save("Initial save", monitor);
	}
}
